"""Writes auto-generated result blocks into docs/METHODS.md between markers."""
from __future__ import annotations

import re

from pipeline import config as C

PATH = C.DOCS / "METHODS.md"


def _replace_block(text: str, name: str, body: str) -> str:
    start, end = f"<!-- AUTO:{name}:START -->", f"<!-- AUTO:{name}:END -->"
    block = f"{start}\n{body.strip()}\n{end}"
    if start in text:
        return re.sub(re.escape(start) + r".*?" + re.escape(end), lambda _: block, text, flags=re.S)
    return text.rstrip() + "\n\n" + block + "\n"


def _fmt(x, nd=3):
    return "—" if x is None else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))


def calibration_md(cal: dict, iv: dict) -> str:
    months = "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split()
    L = ["### Calibration results (auto-generated by `pipeline/calibrate.py`)", "",
         f"Filter variant: `{cal['variant']}` · overlap years: {cal['overlap_years'][0]}–{cal['overlap_years'][-1]} "
         f"({len(cal['overlap_years'])} complete years)", "", f"{cal['fit_note']}.", "",
         "| Month | k_M | k_M 90% CI | k_V | k_V 90% CI |", "|---|---|---|---|---|"]
    for m in range(1, 13):
        lo, hi = cal["k_M_ci"][m] if m in cal["k_M_ci"] else cal["k_M_ci"][str(m)]
        vlo, vhi = cal["k_V_ci"][m] if m in cal["k_V_ci"] else cal["k_V_ci"][str(m)]
        kM = cal["k_M"].get(m, cal["k_M"].get(str(m)))
        kV = cal["k_V"].get(m, cal["k_V"].get(str(m)))
        L.append(f"| {months[m - 1]} | {kM:.3f} | {lo:.3f}–{hi:.3f} | {kV:.3f} | {vlo:.3f}–{vhi:.3f} |")
    L += ["", "**Hold-out test** (leave one overlap year out, predict its monthly union from one sensor):", "",
          "| Factor | MAPE (months ≥ 20 cells) | Bias | Pearson r | 90% interval coverage | months |",
          "|---|---|---|---|---|---|"]
    for k in ["k_M", "k_V"]:
        h = cal["holdout"][k]
        L.append(f"| {k} | {_fmt(h['mape_pct'], 1)}% | {_fmt(h['bias_pct'], 1)}% | {_fmt(h['pearson_r'])} | "
                 f"{_fmt(h['interval_coverage_pct'], 0)}% | {h['n_months']} |")
    L += ["", "The 90% interval reflects uncertainty in the calibration factor only (year-block bootstrap), "
          "not month-to-month variability in the MODIS/VIIRS ratio, so coverage below 90% is expected and is "
          "reported as-is.", ""]
    s = cal["stability"]
    L += ["**Stability** (annual k_M = Σ union / Σ MODIS cells):", "",
          "| Year | " + " | ".join(str(y) for y in s["k_M_by_year"]) + " |",
          "|---|" + "---|" * len(s["k_M_by_year"]),
          "| k_M | " + " | ".join(f"{v:.2f}" for v in s["k_M_by_year"].values()) + " |",
          "| k_V | " + " | ".join(f"{v:.2f}" for v in s["k_V_by_year"].values()) + " |", "",
          f"Mean k_M 2012–2019 = {_fmt(s['k_M_mean_2012_2019'])}, 2020→ = {_fmt(s['k_M_mean_2020_on'])}; "
          f"drift flag (>{int(10)}% change): **{s['drift_flag']}**.", ""]
    st = cal["seam_test"]["step_ratio_2012_16_vs_2007_11"]
    L += ["**Seam test** (mean 2012–2016 ÷ mean 2007–2011, Corrientes region):", "",
          "| Series | Step ratio |", "|---|---|"]
    L += [f"| {k} | {_fmt(v, 2)} |" for k, v in st.items()]
    L += ["", cal["seam_test"]["interpretation"], ""]
    L += ["**Inter-VIIRS check** (§5.2):", ""]
    for name, d in iv.items():
        if not d.get("months"):
            L.append(f"- {name}: {d.get('note', 'no data')}")
            continue
        L.append(f"- {name}: overall {_fmt(d.get('overall'))} over {d['overlap_days']} shared days "
                 f"({d['overlap_start']} → {d['overlap_end']}); per-month range "
                 f"{min(v for v in d['months'].values() if v):.2f}–{max(v for v in d['months'].values() if v):.2f}; "
                 f"**{'scaled, days marked estimated' if d['apply'] else 'within ±10%, used as observed'}**.")
    L += ["", "**Eras** (days in the coverage table):", ""]
    L += [f"- {e}: {v['days']} days ({v['first']} → {v['last']})" for e, v in cal["eras"].items()]
    return "\n".join(L)


def update_methods(cal: dict, iv: dict) -> None:
    text = PATH.read_text(encoding="utf-8")
    text = _replace_block(text, "CALIBRATION", calibration_md(cal, iv))
    PATH.write_text(text, encoding="utf-8")


def update_block(name: str, body: str) -> None:
    text = PATH.read_text(encoding="utf-8")
    PATH.write_text(_replace_block(text, name, body), encoding="utf-8")
